// === Tab: mySketch ===
// For the #WCCChallenge, theme: "arc"
// Nothing 3D here... just 2D arcs! :)

let z = 0;
let ax = 0;
let ay = 0;
let start = 0;
let sweep = 0;
let tstart, tsweep;
const num = 60;
let sf = 0;
let tsf = 255;

function setup() {
	createCanvas(windowWidth, windowHeight);
	noStroke();
	tstart = QUARTER_PI;
	tsweep = HALF_PI;
	strokeWeight(1.5);
}

function draw() {
	background(255);
	sf = lerp(sf, tsf, 0.05);
	translate(width / 2, height / 2);
	z = lerp(z, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0.5, 5), 0.05);
	ax = lerp(ax, map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -3, 3), 0.05);
	ay = lerp(ay, map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -3, 3), 0.05);
	sweep = lerp(sweep, tsweep, 0.05);
	start = lerp(start, tstart, 0.05);
	scale(z);
	for (let i = 0; i < num; i++) {
		fill((i % 2) * 255, sf);
		stroke(0, 255 - sf);
		let r = height - i * height / (num - 1);
		push();
		translate(((num / 2) - r) * noise((i / 80) + frameCount / 200) * ax, ((num / 2) - r) * noise((i / 80) + frameCount / 200) * ay);
		rotate(TAU * noise((i / 120) + frameCount / 200));
		arc(0, 0, r, r, start, start + sweep, PIE);
		pop();
	}
}

function mousePressed() {
	tsweep = random(TAU);
	tstart = random(TAU)
}

function keyPressed() {
	tsf = 255 - tsf;
}
